+// Package archive extracts gzipped tar archives from Crow into an
+// in-memory file map. Diff and TUI layers consume the resulting Module
+// type and never touch the network themselves.
+package archive
+
+import (
+	"archive/tar"
+	"bytes"
+	"compress/gzip"
+	"errors"
+	"fmt"
+	"io"
+)
+
+// Module is the in-memory representation of an extracted module tarball.
+// Keys are forward-slash relative paths. Symlinks are not stored.
+type Module struct {
+	Files map[string][]byte
+}
+
+var (
+	ErrTooLarge   = errors.New("archive exceeds size cap")
+	ErrUnsafePath = errors.New("archive contains unsafe path")
+)
+
+// Extract decompresses and untars tarball into a Module. If the
+// cumulative uncompressed size exceeds maxBytes, Extract returns
+// ErrTooLarge. Paths containing ".." or absolute roots are rejected with
+// ErrUnsafePath. Symlinks are dropped silently (they are not useful
+// inputs to a textual or semantic diff).
+func Extract(tarball []byte, maxBytes int64) (Module, error) {
+	gz, err := gzip.NewReader(bytes.NewReader(tarball))
+	if err != nil {
+		return Module{}, fmt.Errorf("gzip: %w", err)
+	}
+	defer gz.Close()
+
+	tr := tar.NewReader(gz)
+	files := make(map[string][]byte)
+	var total int64
+	for {
+		hdr, err := tr.Next()
+		if errors.Is(err, io.EOF) {
+			break
+		}
+		if err != nil {
+			return Module{}, fmt.Errorf("tar: %w", err)
+		}
+		switch hdr.Typeflag {
+		case tar.TypeReg, tar.TypeRegA: //nolint:staticcheck
+			if err := safePath(hdr.Name); err != nil {
+				return Module{}, err
+			}
+			total += hdr.Size
+			if total > maxBytes {
+				return Module{}, ErrTooLarge
+			}
+			body := make([]byte, hdr.Size)
+			if _, err := io.ReadFull(tr, body); err != nil {
+				return Module{}, fmt.Errorf("reading %s: %w", hdr.Name, err)
+			}
+			files[hdr.Name] = body
+		default:
+			// Directories, symlinks, etc. ignored.
+		}
+	}
+	return Module{Files: files}, nil
+}
+
+func safePath(name string) error {
+	if name == "" {
+		return fmt.Errorf("%w: empty name", ErrUnsafePath)
+	}
+	if name[0] == '/' {
+		return fmt.Errorf("%w: absolute path %q", ErrUnsafePath, name)
+	}
+	// Reject any segment that is "..", or any path containing "..".
+	for i := 0; i < len(name); i++ {
+		if name[i] == '\\' {
+			return fmt.Errorf("%w: backslash in path %q", ErrUnsafePath, name)
+		}
+	}
+	if containsDotDot(name) {
+		return fmt.Errorf("%w: path traversal in %q", ErrUnsafePath, name)
+	}
+	return nil
+}
+
+func containsDotDot(p string) bool {
+	for i := 0; i < len(p); i++ {
+		if p[i] != '.' {
+			continue
+		}
+		// Check for ".." preceded by start-or-slash, followed by slash-or-end.
+		if i+1 < len(p) && p[i+1] == '.' {
+			startOK := i == 0 || p[i-1] == '/'
+			endOK := i+2 == len(p) || p[i+2] == '/'
+			if startOK && endOK {
+				return true
+			}
+		}
+	}
+	return false
+}
diff --git a/apps/birdseye/internal/archive/extract_test.go b/apps/birdseye/internal/archive/extract_test.go
