+++ b/apps/birdseye/internal/archive/extract_test.go
@@ -0,0 +1,82 @@
+package archive
+
+import (
+	"archive/tar"
+	"bytes"
+	"compress/gzip"
+	"testing"
+)
+
+// buildTarGz produces a gzipped tar with the given files in memory.
+// Used by archive, diff, and registry tests.
+func buildTarGz(t *testing.T, files map[string]string) []byte {
+	t.Helper()
+	var buf bytes.Buffer
+	gz := gzip.NewWriter(&buf)
+	tw := tar.NewWriter(gz)
+	for name, body := range files {
+		hdr := &tar.Header{
+			Name: name,
+			Mode: 0o644,
+			Size: int64(len(body)),
+		}
+		if err := tw.WriteHeader(hdr); err != nil {
+			t.Fatalf("WriteHeader %s: %v", name, err)
+		}
+		if _, err := tw.Write([]byte(body)); err != nil {
+			t.Fatalf("Write %s: %v", name, err)
+		}
+	}
+	if err := tw.Close(); err != nil {
+		t.Fatal(err)
+	}
+	if err := gz.Close(); err != nil {
+		t.Fatal(err)
+	}
+	return buf.Bytes()
+}
+
+func TestExtractHappyPath(t *testing.T) {
+	in := map[string]string{
+		"main.tf":      "resource \"aws_s3_bucket\" \"x\" {}\n",
+		"variables.tf": "variable \"name\" { type = string }\n",
+		"README.md":    "hello\n",
+	}
+	tgz := buildTarGz(t, in)
+
+	mod, err := Extract(tgz, 1<<20)
+	if err != nil {
+		t.Fatalf("Extract: %v", err)
+	}
+	if len(mod.Files) != len(in) {
+		t.Fatalf("got %d files, want %d", len(mod.Files), len(in))
+	}
+	for name, want := range in {
+		got, ok := mod.Files[name]
+		if !ok {
+			t.Errorf("missing file: %s", name)
+			continue
+		}
+		if string(got) != want {
+			t.Errorf("%s body = %q, want %q", name, got, want)
+		}
+	}
+}
+
+func TestExtractEmptyArchive(t *testing.T) {
+	tgz := buildTarGz(t, nil)
+	mod, err := Extract(tgz, 1<<20)
+	if err != nil {
+		t.Fatalf("Extract empty: %v", err)
+	}
+	if len(mod.Files) != 0 {
+		t.Errorf("expected 0 files, got %d", len(mod.Files))
+	}
+}
+
+func TestExtractMalformedGzip(t *testing.T) {
+	_, err := Extract([]byte("not a gzip"), 1<<20)
+	if err == nil {
+		t.Fatal("expected error on malformed input")
+	}
+}
